function validate([grid, r1, c1, r2, c2]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 100) return 'grid needs 1 to 100 rows.';
  const m = grid.length;
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1 || n > 100) return 'Each row of grid needs 1 to 100 cells.';
  if (grid.some(line => !Array.isArray(line) || line.length !== n)) return 'Every row of grid must have the same length.';
  if (grid.some(line => line.some(v => !Number.isInteger(v) || v < 0 || v > 100))) return 'Each cell is an integer from 0 to 100.';
  const inside = (r, c) => Number.isInteger(r) && Number.isInteger(c) && r >= 0 && r < m && c >= 0 && c < n;
  if (!inside(r1, c1)) return '(r1, c1) must be a cell of grid.';
  if (!inside(r2, c2)) return '(r2, c2) must be a cell of grid.';
  if (grid[r1][c1] === 0 || grid[r2][c2] === 0) return 'The start and the target must be open cells.';
  if (r1 === r2 && c1 === c2) return 'The start and the target must be different cells.';
  const seen = grid.map(line => line.map(() => false));
  const stack = [[r1, c1]];
  seen[r1][c1] = true;
  let reached = 1;
  while (stack.length) {
    const [r, c] = stack.pop();
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] > 0 && !seen[nr][nc]) {
        seen[nr][nc] = true;
        reached++;
        stack.push([nr, nc]);
      }
    }
  }
  if (reached > 1500) return 'The local judge supports at most 1,500 open cells reachable from the start.';
  return null;
}

