function adapt(input, solve, kit) {
  const [grid, r1, c1, r2, c2] = input;
  const steps = new Map([['U', [-1, 0]], ['D', [1, 0]], ['L', [0, -1]], ['R', [0, 1]]]);
  const open = grid.reduce((sum, line) => sum + line.filter(v => v > 0).length, 0);
  const limit = 50 * open + 1000;
  let row = r1, col = c1, calls = 0;
  const count = () => {
    calls++;
    if (calls > limit) throw new Error('Too many GridMaster calls; make sure each cell is explored only once.');
  };
  const neighbour = (direction) => {
    count();
    if (!steps.has(direction)) throw new Error(`Unknown direction ${JSON.stringify(direction)}; use 'U', 'D', 'L' or 'R'.`);
    const [dr, dc] = steps.get(direction);
    const r = row + dr, c = col + dc;
    return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c] > 0 ? [r, c] : null;
  };
  // The grid and the robot's position stay inside this closure; the solution sees only the three methods.
  const master = Object.freeze({
    canMove(direction) { return neighbour(direction) !== null; },
    move(direction) {
      const cell = neighbour(direction);
      if (cell === null) return -1;
      row = cell[0];
      col = cell[1];
      return grid[row][col];
    },
    isTarget() { count(); return row === r2 && col === c2; },
  });
  return solve(master);
}

