function findShortestPath(master) {
  const steps = { U: [-1, 0, 'D'], D: [1, 0, 'U'], L: [0, -1, 'R'], R: [0, 1, 'L'] };
  const cost = new Map([['0,0', 0]]);
  let target = null;

  const explore = (row, col) => {
    if (master.isTarget()) target = `${row},${col}`;
    for (const [dir, [dr, dc, back]] of Object.entries(steps)) {
      const next = `${row + dr},${col + dc}`;
      if (cost.has(next) || !master.canMove(dir)) continue;
      cost.set(next, master.move(dir));
      explore(row + dr, col + dc);
      master.move(back);
    }
  };
  explore(0, 0);
  if (target === null) return -1;

  const heap = [[0, 0, 0]];
  const push = (item) => {
    heap.push(item);
    for (let i = heap.length - 1; i > 0; ) {
      const parent = (i - 1) >> 1;
      if (heap[parent][0] <= heap[i][0]) break;
      [heap[parent], heap[i]] = [heap[i], heap[parent]];
      i = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    heap[0] = last;
    for (let i = 0; ; ) {
      let smallest = i;
      for (const child of [2 * i + 1, 2 * i + 2]) {
        if (child < heap.length && heap[child][0] < heap[smallest][0]) smallest = child;
      }
      if (smallest === i) break;
      [heap[smallest], heap[i]] = [heap[i], heap[smallest]];
      i = smallest;
    }
    return top;
  };

  const dist = new Map([['0,0', 0]]);
  while (heap.length > 0) {
    const [total, row, col] = pop();
    const key = `${row},${col}`;
    if (key === target) return total;
    if (total > dist.get(key)) continue;
    for (const [dr, dc] of Object.values(steps)) {
      const next = `${row + dr},${col + dc}`;
      if (!cost.has(next)) continue;
      const candidate = total + cost.get(next);
      if (!dist.has(next) || candidate < dist.get(next)) {
        dist.set(next, candidate);
        push([candidate, row + dr, col + dc]);
      }
    }
  }
  return -1;
}

