function findShortestPath(master) {
  // Explore with an explicit path stack, probing with move() itself, then relax distances until nothing changes.
  const dr = { U: -1, D: 1, L: 0, R: 0 };
  const dc = { U: 0, D: 0, L: -1, R: 1 };
  const opposite = { U: 'D', D: 'U', L: 'R', R: 'L' };
  const cells = new Map([['0,0', 0]]);
  const walls = new Set();
  const path = [];
  let r = 0, c = 0, goal = master.isTarget() ? '0,0' : null;
  for (;;) {
    let moved = false;
    for (const d of ['R', 'L', 'D', 'U']) {
      const key = (r + dr[d]) + ',' + (c + dc[d]);
      if (cells.has(key) || walls.has(key)) continue;
      const paid = master.move(d);
      if (paid === -1) { walls.add(key); continue; }
      r += dr[d];
      c += dc[d];
      cells.set(key, paid);
      path.push(d);
      if (master.isTarget()) goal = key;
      moved = true;
      break;
    }
    if (moved) continue;
    if (!path.length) break;
    const back = opposite[path.pop()];
    master.move(back);
    r += dr[back];
    c += dc[back];
  }
  if (goal === null) return -1;
  const best = new Map([...cells.keys()].map(k => [k, k === '0,0' ? 0 : Infinity]));
  for (let changed = true; changed; ) {
    changed = false;
    for (const [key, price] of cells) {
      const [x, y] = key.split(',').map(Number);
      for (const nk of [(x + 1) + ',' + y, (x - 1) + ',' + y, x + ',' + (y + 1), x + ',' + (y - 1)]) {
        if (best.has(nk) && best.get(nk) + price < best.get(key)) {
          best.set(key, best.get(nk) + price);
          changed = true;
        }
      }
    }
  }
  return best.get(goal);
}

