function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  for (;;) {
    const m = size === 'large' ? 60 + pick(41) : 1 + pick(5);
    const n = size === 'large' ? 60 + pick(41) : 1 + pick(5);
    if (m * n < 2) continue;
    const wallRate = (size === 'large' ? [0.1, 0.25, 0.35] : [0, 0.15, 0.3, 0.45])[pick(size === 'large' ? 3 : 4)];
    const maxCost = [1, 3, 10, 100][pick(4)];
    const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < wallRate ? 0 : 1 + pick(maxCost))));
    const r1 = pick(m), c1 = pick(n);
    if (grid[r1][c1] === 0) grid[r1][c1] = 1 + pick(maxCost);
    // Keep at most 1,500 reachable open cells: a prefix of the breadth-first order stays connected.
    const seen = grid.map(line => line.map(() => false));
    const order = [[r1, c1]];
    seen[r1][c1] = true;
    for (let i = 0; i < order.length; i++) {
      const [r, c] = order[i];
      for (const [dr, dc] of dirs) {
        const nr = r + dr, nc = c + dc;
        if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] > 0 && !seen[nr][nc]) {
          seen[nr][nc] = true;
          order.push([nr, nc]);
        }
      }
    }
    for (const [r, c] of order.slice(1500)) grid[r][c] = 0;
    const reachable = order.slice(1, 1500);
    const isolated = [];
    for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) if (grid[r][c] > 0 && !seen[r][c]) isolated.push([r, c]);
    const pool = isolated.length && rand() < 0.2 ? isolated : reachable.length ? reachable : isolated;
    if (!pool.length) continue;
    const [r2, c2] = pool[pick(pool.length)];
    return [grid, r1, c1, r2, c2];
  }
}
